const { useState, useRef, useId } = React;

function ConsentForm() {
  const checkboxId = useId();
  const helpId = useId();
  const errorId = useId();
  const statusId = useId();

  const [agreed, setAgreed] = useState(false);
  const [error, setError] = useState("");
  const [submitted, setSubmitted] = useState(false);
  const checkboxRef = useRef(null);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!agreed) {
      setError("You must agree to the terms of use to continue.");
      setSubmitted(false);
      if (checkboxRef.current) checkboxRef.current.focus();
      return;
    }
    setError("");
    setSubmitted(true);
  };

  const handleChange = (e) => {
    setAgreed(e.target.checked);
    if (e.target.checked && error) setError("");
  };

  const describedBy = error ? `${helpId} ${errorId}` : helpId;

  return (
    <form className="card" noValidate onSubmit={handleSubmit}>
      <h1>Terms of use</h1>
      <p className="lede">
        Please review and accept our terms before creating your account.
      </p>
      <p className="required-key">
        <span className="required-mark" aria-hidden="true">*</span> indicates a
        required field
      </p>

      <div className="form-field">
        <div className="checkbox-row">
          <input
            id={checkboxId}
            ref={checkboxRef}
            type="checkbox"
            required
            checked={agreed}
            onChange={handleChange}
            aria-describedby={describedBy}
            aria-invalid={error ? "true" : "false"}
          />
          <label htmlFor={checkboxId}>
            I agree to the{" "}
            <a href="/terms" target="_blank" rel="noopener noreferrer">
              terms of use
            </a>
            <span className="required-mark" aria-hidden="true">*</span>
          </label>
          <p id={helpId} className="help-text">
            You must accept the terms to create an account. You can review them
            at any time from your account settings.
          </p>
          {error && (
            <p id={errorId} className="error-text">
              {error}
            </p>
          )}
        </div>
      </div>

      <div className="actions">
        <button type="submit">Create account</button>
      </div>

      <div
        id={statusId}
        className={submitted ? "status success" : ""}
        role="status"
        aria-live="polite"
      >
        {submitted ? "Thanks — your agreement has been recorded." : ""}
      </div>
    </form>
  );
}

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(<ConsentForm />);

